import React, { useState, useEffect, forwardRef, useImperativeHandle } from 'react';
import preval from 'preval.macro';
import { CSVLink } from "react-csv";
import {
    Modal,
    ModalHeader,
    ModalBody,
    ModalFooter,
    ModalButton,
    ROLE,
    SIZE
} from 'baseui/modal';
import { StyledLink } from "baseui/link";
import db from '../Components/Db';
import { resetPwaChromeColor, setPwaChromeColor } from '../Components/PwaChrome';

const ABOUT_SAFE_AREA_COLOR = '#8f8f8f';

const About = forwardRef((props, ref) => {
    const [drawerOpen, setDrawerOpen] = useState(false);
    const dateTimeStamp = preval`module.exports = new Date().toLocaleString();`
    const csvLinkEl = React.useRef();
    const [data, setData] = useState([]);

    useImperativeHandle(ref, () => {
        return {
            showDrawer: showDrawer,
            hideDrawer: hideDrawer
        }
    });

    const showDrawer = (identifier, title) => {
        setPwaChromeColor(ABOUT_SAFE_AREA_COLOR);
        setDrawerOpen(true);
    };

    const hideDrawer = () => {
        setDrawerOpen(false);
        resetPwaChromeColor();
    };

    const headers = [
        { label: "identifier", key: "id" },
        { label: "title", key: "title" },
        { label: "page", key: "page" },
        { label: "archived", key: "archived" },
        { label: "read", key: "read" }
    ];

    const downloadReport = async () => {
        db.collection
            .toArray()
            .then((items) => {
                setData(items);
            });
    }

    useEffect(() => {
        if (csvLinkEl.current !== undefined) {
            setTimeout(() => {
                csvLinkEl.current.link.click();
            });
        }
    }, [data]);

    useEffect(() => {
        return () => {
            resetPwaChromeColor();
        };
    }, []);

    return (
        <Modal
            isOpen={drawerOpen}
            onClose={hideDrawer}
            closeable
            animate
            autoFocus
            size={SIZE.default}
            role={ROLE.dialog}
            overrides={{
                Root: {
                    style: {
                        zIndex: 2100
                    }
                },
                DialogContainer: {
                    style: {
                        zIndex: 2100
                    }
                },
                Dialog: {
                    style: {
                        zIndex: 2101
                    }
                }
            }}>
            <ModalHeader>LoboReader<br />for Internet Archive</ModalHeader>
            <ModalBody>
                Build date: {dateTimeStamp}<br /><br />
                LoboReader is an unofficial mobile reader for the Internet Archive "Magazine Rack".<br /><br />
                Developed by Michal Galinski.<br/><br/>
                <StyledLink animateUnderline onClick={downloadReport}>Click here</StyledLink> to download your reading list.<br /><br />
                <CSVLink headers={headers} data={data} ref={csvLinkEl} filename="LoboReader-export.csv"></CSVLink>
                For changelog, docs &amp; licensing please visit project page on GitHub.
            </ModalBody>
            <ModalFooter style={{paddingBottom: '24px'}}>
                <a href="mailto:developer@galu.info" target="_blank" rel="noreferrer" style={{paddingRight: '12px'}}><ModalButton kind="primiary">Contact</ModalButton></a>
                <a href="https://github.com/gitGalu/LoboReader" target="_blank" rel="noreferrer"><ModalButton kind="primiary">Visit GitHub</ModalButton></a>
            </ModalFooter>
        </Modal>
    )
});

export default About;
